class BMP280_Simulator(BaseVirtualSensor):
    def __init__(self):
        super().__init__()

        # Initialize registers with their reset values
        self.regs = {
            0xD0: 0x58,  # id
            0xE0: 0x00,  # reset
            0xF3: 0x00,  # status
            0xF4: 0x00,  # ctrl_meas
            0xF5: 0x00,  # config
            0xF7: 0x80,  # press_msb
            0xF8: 0x00,  # press_lsb
            0xF9: 0x00,  # press_xlsb
            0xFA: 0x80,  # temp_msb
            0xFB: 0x00,  # temp_lsb
            0xFC: 0x00,  # temp_xlsb
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        # Check if the address is valid and the register exists
        if addr not in self.regs:
            raise ValueError(f'Invalid register address: {addr}')

        # Return the value of the register
        if nbytes == 1:
            return (self.regs[addr] & 0xFF00) >> 8
        elif nbytes == 2:
            return self.regs[addr]
        else:
            raise ValueError(f'Invalid number of bytes: {nbytes}')

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        # Check if the address is valid and the register exists
        if addr not in self.regs:
            raise ValueError(f'Invalid register address: {addr}')

        # Check if the data can be stored in the register
        if nbytes == 1:
            if data < 0 or data > 0xFF:
                raise ValueError(f'Invalid data for 1 byte write: {data}')
            self.regs[addr] = (self.regs[addr] & 0x00FF) | (data << 8)
        elif nbytes == 2:
            if data < 0 or data > 0xFFFF:
                raise ValueError(f'Invalid data for 2 bytes write: {data}')
            self.regs[addr] = data
        else:
            raise ValueError(f'Invalid number of bytes: {nbytes}')

